//! The tray icon. On a Mac, the menu bar icon: a monochrome template of the agent symbol, one image per state
//! (generated by `apps/desktop/scripts/icons.ts` in CI; macOS tints template images for light and dark menu
//! bars by itself), shown while this computer works for agents or when the person chose it, and opening the
//! popover. On Windows and Linux there is no Dock and closing the window only hides it, so the icon is always
//! there, the app icon the person picked (app_icon.rs), with a native menu: Show or Hide the window (whichever it
//! isn't), the servers, pausing the agents here, the server here's state with Start or Stop, Preferences, Quit. On
//! Linux the menu is the right click's, and a left click shows or hides the window (the StatusNotifierItem
//! backend, Cargo.toml).

use tauri::AppHandle;

const TRAY_ID: &str = "main";

#[cfg(target_os = "linux")]
static STATUS_NOTIFIER_HOST_REGISTERED: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

#[cfg(target_os = "macos")]
mod icons {
    pub const IDLE: &[u8] = include_bytes!("../icons/tray/idle.png");
    pub const WORKING: &[u8] = include_bytes!("../icons/tray/working.png");
    pub const PAUSED: &[u8] = include_bytes!("../icons/tray/paused.png");
    pub const OFFLINE: &[u8] = include_bytes!("../icons/tray/offline.png");
    pub const UPDATE: &[u8] = include_bytes!("../icons/tray/update.png");
    /// An agent is in its browser: a ring in the corner.
    pub const BROWSING: &[u8] = include_bytes!("../icons/tray/browsing.png");
    /// An agent needs a person in its browser: a filled dot in the corner.
    pub const NEEDS: &[u8] = include_bytes!("../icons/tray/needs.png");
}

const STATES: &[&str] = &["idle", "working", "paused", "offline", "update", "browsing", "needs"];

#[cfg(target_os = "macos")]
fn bytes_for(state: &str) -> Option<&'static [u8]> {
    use icons::*;
    match state {
        "idle" => Some(IDLE),
        "working" => Some(WORKING),
        "paused" => Some(PAUSED),
        "offline" => Some(OFFLINE),
        "update" => Some(UPDATE),
        "browsing" => Some(BROWSING),
        "needs" => Some(NEEDS),
        _ => None,
    }
}

#[cfg(target_os = "macos")]
pub fn create(app: &AppHandle) -> tauri::Result<()> {
    use tauri::image::Image;
    use tauri::tray::{MouseButton, MouseButtonState, TrayIconBuilder, TrayIconEvent};
    let tray = TrayIconBuilder::with_id(TRAY_ID)
        .tooltip("agentes.chat")
        .icon(Image::from_bytes(icons::IDLE)?)
        .icon_as_template(true)
        .on_tray_icon_event(|tray, event| {
            // The positioner needs every tray event to know where the icon is.
            tauri_plugin_positioner::on_tray_event(tray.app_handle(), &event);
            if let TrayIconEvent::Click {
                button: MouseButton::Left | MouseButton::Right,
                button_state: MouseButtonState::Up,
                ..
            } = event
            {
                crate::toggle_popover(tray.app_handle());
            }
        })
        .build(app)?;
    // Off until the popover says (`tray_visible`): with agentes.chat nothing of this computer shows.
    tray.set_visible(false)?;
    Ok(())
}

#[cfg(not(target_os = "macos"))]
pub fn create(app: &AppHandle) -> tauri::Result<()> {
    let mut builder = tauri::tray::TrayIconBuilder::with_id(TRAY_ID)
        .tooltip("agentes.chat")
        .menu(&menu(app)?)
        .show_menu_on_left_click(true);
    if let Some(icon) = app.default_window_icon() {
        builder = builder.icon(icon.clone());
    }
    #[cfg(target_os = "linux")]
    {
        use tauri::tray::{MouseButton, TrayIconEvent};
        builder = builder.on_tray_icon_event(|tray, event| {
            if let TrayIconEvent::Click { button: MouseButton::Left, .. } = event {
                toggle_window(tray.app_handle());
            }
        });
    }
    // The icon is optional: without a StatusNotifier host the backend's spawn returns Err (ksni's `Watcher` or
    // `WontShow`), and a setup that fails would abort the whole app. It is not retried: the crate registers the
    // item only at spawn (a watcher that goes away later is survived by the crate; nothing re-registers a failed
    // one), so the icon waits for the next start. Everything else reads the tray through `tray_by_id`, which
    // is then None, and `shown()` keeps the window reachable.
    if let Err(err) = builder.build(app) {
        eprintln!("agentes.chat: no tray icon: {err}");
    }
    #[cfg(target_os = "linux")]
    watch_status_notifier_host();
    Ok(())
}

/// Session-bus work stays asynchronous so a missing or slow tray host cannot stall GTK window handling.
#[cfg(target_os = "linux")]
fn watch_status_notifier_host() {
    use webkit2gtk::gio;

    gio::bus_get(gio::BusType::Session, None::<&gio::Cancellable>, |result| {
        let Ok(bus) = result else { return };

        let host = "org.kde.StatusNotifierWatcher";
        for (signal, registered) in [
            ("StatusNotifierHostRegistered", true),
            ("StatusNotifierHostUnregistered", false),
        ] {
            bus.signal_subscribe(
                Some(host),
                Some(host),
                Some(signal),
                Some("/StatusNotifierWatcher"),
                None,
                gio::DBusSignalFlags::NONE,
                move |_, _, _, _, _, _| {
                    STATUS_NOTIFIER_HOST_REGISTERED
                        .store(registered, std::sync::atomic::Ordering::Relaxed);
                },
            );
        }

        let args = webkit2gtk::glib::Variant::from((host, "IsStatusNotifierHostRegistered"));
        bus.call(
            Some(host),
            "/StatusNotifierWatcher",
            "org.freedesktop.DBus.Properties",
            "Get",
            Some(&args),
            None,
            gio::DBusCallFlags::NO_AUTO_START,
            500,
            None::<&gio::Cancellable>,
            |result| {
                let registered = result
                    .ok()
                    .and_then(|reply| reply.child_value(0).as_variant())
                    .and_then(|value| value.get::<bool>())
                    .unwrap_or(false);
                STATUS_NOTIFIER_HOST_REGISTERED
                    .store(registered, std::sync::atomic::Ordering::Relaxed);
            },
        );
    });
}

/// Windows and Linux: the app icon the person picked (app_icon.rs), which the tray shows like the windows. Without a
/// tray icon there is nothing to change.
#[cfg(not(target_os = "macos"))]
pub fn set_app_icon(app: &AppHandle, image: tauri::image::Image<'static>) {
    if let Some(tray) = app.tray_by_id(TRAY_ID) {
        if let Err(err) = tray.set_icon(Some(image)) {
            eprintln!("agentes.chat: the tray icon didn't change: {err}");
        }
    }
}

/// Linux, a left click on the icon: what the menu's first item would do, Hide or Show.
#[cfg(target_os = "linux")]
fn toggle_window(app: &AppHandle) {
    if SHOWING.load(std::sync::atomic::Ordering::Relaxed) {
        hide_window(app);
    } else {
        crate::open_app(app);
    }
}

/// Windows and Linux: whether the site's window is on screen (shown and not minimized).
#[cfg(not(target_os = "macos"))]
fn window_on_screen(app: &AppHandle) -> bool {
    use tauri::Manager;
    app.get_window(crate::main_window::LABEL)
        .is_some_and(|w| w.is_visible().unwrap_or(false) && !w.is_minimized().unwrap_or(false))
}

/// Windows and Linux, the menu's Hide (and the icon's click on Linux): off screen as closing it does.
#[cfg(not(target_os = "macos"))]
pub fn hide_window(app: &AppHandle) {
    use tauri::Manager;
    if let Some(window) = app.get_window(crate::main_window::LABEL) {
        crate::window_state::remember(&window, false);
        let _ = window.hide();
    }
    window_going(app, false);
}

/// Windows and Linux: the tray's menu, with the labels the popover sent (each key until then).
#[cfg(not(target_os = "macos"))]
fn menu(app: &AppHandle) -> tauri::Result<tauri::menu::Menu<tauri::Wry>> {
    use tauri::menu::{Menu, MenuItemBuilder, PredefinedMenuItem, SubmenuBuilder};
    let labels = crate::menus::labels(app);
    let l = |key: &str| labels.get(key).cloned().unwrap_or_else(|| key.to_string());
    let item = |id: &str, key: &str| MenuItemBuilder::with_id(format!("app:{id}"), l(key)).build(app);
    let menu = Menu::new(app)?;
    let showing = SHOWING.load(std::sync::atomic::Ordering::Relaxed);
    menu.append(&if showing { item("hide", "trayHide")? } else { item("open", "trayShow")? })?;
    menu.append(&crate::menus::servers_menu(app, &l)?)?;
    // Agents work here (Linux): pause them for the whole computer, or resume.
    if agents_work_here(app) {
        let pause = SubmenuBuilder::new(app, l("trayPause"))
            .item(&item("pause1h", "trayPause1h")?)
            .item(&item("pauseTomorrow", "trayPauseTomorrow")?)
            .item(&item("pauseManual", "trayPauseManual")?)
            .build()?;
        menu.append(&PredefinedMenuItem::separator(app)?)?;
        menu.append(&pause)?;
        menu.append(&item("resume", "trayResume")?)?;
    }
    // The server here: its state, and Start or Stop.
    if crate::local_server::runs(app) {
        use crate::local_server::Phase;
        let phase = crate::local_server::phase(app);
        let (state, action) = match phase {
            Phase::Running => ("serverRunning", ("hereStop", "serverStop")),
            Phase::Starting | Phase::Updating | Phase::Restarting => ("serverStarting", ("hereStop", "serverStop")),
            Phase::Failing => ("serverFailing", ("hereStart", "serverStart")),
            Phase::Stopped | Phase::Off => ("serverStopped", ("hereStart", "serverStart")),
        };
        menu.append(&PredefinedMenuItem::separator(app)?)?;
        let line = format!("{} · {}", l("serverTitle"), l(state));
        menu.append(&MenuItemBuilder::new(line).enabled(false).build(app)?)?;
        menu.append(&item(action.0, action.1)?)?;
    }
    menu.append(&PredefinedMenuItem::separator(app)?)?;
    menu.append(&item("prefs", "trayPrefs")?)?;
    menu.append(&item("quit", "trayQuit")?)?;
    Ok(menu)
}

#[cfg(not(target_os = "macos"))]
fn agents_work_here(app: &AppHandle) -> bool {
    use tauri::Manager;
    app.state::<crate::runners::Runners>().any_paired()
}

/// Whether agents worked here when the tray's menu was last built (0 no, 1 yes, 2 not built yet).
#[cfg(not(target_os = "macos"))]
static BUILT_WITH_AGENTS: std::sync::atomic::AtomicU8 = std::sync::atomic::AtomicU8::new(2);

/// Where the site's window is, as last asked for or seen (Windows, Linux): the tray's menu says Hide while it is
/// on screen, else Show.
#[cfg(not(target_os = "macos"))]
static SHOWING: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

/// The app just showed or hid the window. Told rather than read: on Linux the window takes the request a moment
/// later, and asked right away it still answers as before.
pub fn window_going(app: &AppHandle, on_screen: bool) {
    #[cfg(not(target_os = "macos"))]
    follow(app, on_screen);
    #[cfg(target_os = "macos")]
    let _ = (app, on_screen);
}

/// The window gained or lost focus: shown, hidden or minimized, perhaps by the system. Read where it is now.
pub fn window_changed(app: &AppHandle) {
    #[cfg(not(target_os = "macos"))]
    follow(app, window_on_screen(app));
    #[cfg(target_os = "macos")]
    let _ = app;
}

/// The menu again only when its Show or Hide is wrong.
#[cfg(not(target_os = "macos"))]
fn follow(app: &AppHandle, on_screen: bool) {
    if SHOWING.swap(on_screen, std::sync::atomic::Ordering::Relaxed) != on_screen {
        refresh(app);
    }
}

/// The tray's menu again (Windows, Linux): the labels or the servers changed.
pub fn refresh(app: &AppHandle) {
    #[cfg(not(target_os = "macos"))]
    if let (Some(tray), Ok(menu)) = (app.tray_by_id(TRAY_ID), menu(app)) {
        BUILT_WITH_AGENTS.store(u8::from(agents_work_here(app)), std::sync::atomic::Ordering::Relaxed);
        let _ = tray.set_menu(Some(menu));
    }
    // The Mac's menu bar has the server here's state and Stop or Start (menus.rs `here_menu`).
    #[cfg(target_os = "macos")]
    crate::menus::here_changed(app);
}

pub fn set_state(app: &AppHandle, state: &str) -> Result<(), String> {
    if !STATES.contains(&state) {
        return Err(format!("unknown tray state: {state}"));
    }
    #[cfg(target_os = "macos")]
    {
        let bytes = bytes_for(state).ok_or("no image")?;
        let tray = app.tray_by_id(TRAY_ID).ok_or("no tray icon")?;
        let image = tauri::image::Image::from_bytes(bytes).map_err(|e| e.to_string())?;
        tray.set_icon(Some(image)).map_err(|e| e.to_string())?;
        tray.set_icon_as_template(true).map_err(|e| e.to_string())?;
    }
    // Windows and Linux keep the app icon the person picked (template images are a Mac's); the menu follows
    // whether agents work here, which changes along with the state.
    #[cfg(not(target_os = "macos"))]
    if BUILT_WITH_AGENTS.load(std::sync::atomic::Ordering::Relaxed) != u8::from(agents_work_here(app)) {
        refresh(app);
    }
    Ok(())
}

/// Linux: whether the app's tray icon shows somewhere. The icon is drawn only by a
/// StatusNotifier host (KDE's panel, GNOME's AppIndicator extension, Waybar's tray), which registers with the
/// watcher on the session bus. Without one the icon is nowhere, and a hidden window could not be opened again.
#[cfg(target_os = "linux")]
pub fn shown(app: &AppHandle) -> bool {
    if app.tray_by_id(TRAY_ID).is_none() {
        return false;
    }
    STATUS_NOTIFIER_HOST_REGISTERED.load(std::sync::atomic::Ordering::Relaxed)
}

/// Startup has no window to stall, so preserve the bounded host check that decides whether login starts hidden.
/// Later window events use `shown()` and the async watcher, avoiding a session-bus wait on GTK's thread.
#[cfg(target_os = "linux")]
pub fn shown_at_startup(app: &AppHandle) -> bool {
    if app.tray_by_id(TRAY_ID).is_none() {
        STATUS_NOTIFIER_HOST_REGISTERED.store(false, std::sync::atomic::Ordering::Relaxed);
        return false;
    }

    use webkit2gtk::gio;
    use webkit2gtk::glib::Variant;

    let registered = gio::bus_get_sync(gio::BusType::Session, None::<&gio::Cancellable>)
        .ok()
        .and_then(|bus| {
            let args = Variant::from(("org.kde.StatusNotifierWatcher", "IsStatusNotifierHostRegistered"));
            bus.call_sync(
                Some("org.kde.StatusNotifierWatcher"),
                "/StatusNotifierWatcher",
                "org.freedesktop.DBus.Properties",
                "Get",
                Some(&args),
                None,
                gio::DBusCallFlags::NO_AUTO_START,
                500,
                None::<&gio::Cancellable>,
            )
            .ok()
        })
        .and_then(|reply| reply.child_value(0).as_variant())
        .and_then(|value| value.get::<bool>())
        .unwrap_or(false);
    STATUS_NOTIFIER_HOST_REGISTERED.store(registered, std::sync::atomic::Ordering::Relaxed);
    registered
}

/// On a Mac, whether the menu bar icon shows (the popover decides: agents here, or the person's choice).
#[tauri::command]
pub fn tray_visible(app: AppHandle, window: tauri::Window, show: bool) -> Result<(), String> {
    if !matches!(window.label(), "popover" | "prefs") {
        return Err("only the app's own windows set this".into());
    }
    #[cfg(target_os = "macos")]
    if let Some(tray) = app.tray_by_id(TRAY_ID) {
        tray.set_visible(show).map_err(|e| e.to_string())?;
    }
    #[cfg(not(target_os = "macos"))]
    let _ = (app, show);
    Ok(())
}
